F = (5,0);
P = (6,3*sqrt(5)/2);
Q = (16/5,3*sqrt(5)/2);

draw(F--P--Q);
draw((16/5,-1)--(16/5,4),dashed);

dot("$F$", F, S);
dot("$P$", P, NE);
dot("$Q$", Q, W);

label("$x = \frac{16}{5}$", (16/5,-1), S);
[/asy]

